/*
 * dd_load.h - the game data (heroes, monsters, skills, text...) is NOT in the program.
 * The extractor builds assets/gen/dd_data.bin from the user's own game copy; dd_data_load() reads it
 * into the dd_* tables declared in dd_types.h.  dd_load_gen.c is generated by tools/ddbin.py.
 */
#ifndef DD_LOAD_H
#define DD_LOAD_H

/* 0 on success, negative on a bad / mismatched blob (-3: made by a different extractor version). */
int dd_data_load(const void *blob, int size);

#endif
